#include <stdio.h>

typedef struct {
    int x;
    int y;
} Point;

int distance_squared(Point a, Point b) {
    int dx = a.x - b.x;
    int dy = a.y - b.y;
    return dx * dx + dy * dy;
}

int main() {
    Point origin = {0, 0};
    Point a = {3, 4};
    Point b = {6, 8};
    printf("%d\n", distance_squared(origin, a));
    printf("%d\n", distance_squared(origin, b));
    return 0;
}
